def preorder_traversal(inorder: str, postorder: str) -> str:
    """
    Reconstructs the binary tree from its inorder and postorder traversals and
    returns the preorder traversal as a string.

    Args:
        inorder (str): The inorder traversal of the binary tree.
        postorder (str): The postorder traversal of the binary tree.

    Returns:
        str: The preorder traversal of the binary tree.
    """
    if len(inorder) != len(postorder):
        raise ValueError("The lengths of inorder and postorder strings must be equal.")
    n = len(inorder)
    if n == 0:
        return ""

    # Map each character to its index in inorder for O(1) lookups
    index_map = {}
    for idx, ch in enumerate(inorder):
        if ch in index_map:
            raise ValueError(f"Duplicate character '{ch}' found in inorder traversal.")
        index_map[ch] = idx

    def build(in_left: int, in_right: int, post_left: int, post_right: int) -> str:
        if in_left > in_right or post_left > post_right:
            return ""
        root = postorder[post_right]
        if root not in index_map:
            raise ValueError(f"Character '{root}' from postorder not found in inorder.")
        in_root_idx = index_map[root]
        if in_root_idx < in_left or in_root_idx > in_right:
            raise ValueError(f"Invalid root index for character '{root}'.")
        left_size = in_root_idx - in_left
        left_pre = build(in_left, in_root_idx - 1, post_left, post_left + left_size - 1)
        right_pre = build(in_root_idx + 1, in_right, post_left + left_size, post_right - 1)
        return root + left_pre + right_pre

    return build(0, n - 1, 0, n - 1)

def string_transformation(A: str, B: str, rules: list) -> Union[int, str]:
    """
    Perform string transformation from A to B using a set of transformation rules.
    Uses BFS up to 10 steps. Returns minimal steps if possible, else "NO ANSWER!".
    """
    if not isinstance(A, str) or not isinstance(B, str):
        return "NO ANSWER!"
    if not isinstance(rules, list):
        return "NO ANSWER!"
    if A == B:
        return 0

    max_depth = 10
    visited = {A}
    queue = [(A, 0)]

    while queue:
        current, steps = queue.pop(0)
        if steps >= max_depth:
            continue

        for rule in rules:
            if not (isinstance(rule, tuple) and len(rule) == 2):
                continue
            src, tgt = rule
            if not isinstance(src, str) or not isinstance(tgt, str) or not src:
                continue

            idx = 0
            while True:
                pos = current.find(src, idx)
                if pos == -1:
                    break
                new_str = current[:pos] + tgt + current[pos + len(src):]
                if new_str == B:
                    return steps + 1
                if new_str not in visited:
                    visited.add(new_str)
                    queue.append((new_str, steps + 1))
                idx = pos + 1

    return "NO ANSWER!"

def is_prime(num: int) -> bool:
    """
    Determine whether a given integer is a prime number.

    A prime number is a natural number greater than 1 that has no positive divisors other than 1 and itself. The function checks for primality by eliminating non-prime numbers using several tests. First, it handles edge cases for numbers less than or equal to 1, which are not prime, and small numbers (2 and 3) which are prime. It then checks for divisibility by 2 and 3. For larger numbers, it uses a 6k +/- 1 optimization to test for factors up to the square root of the number.

    Args:
        num (int): The integer to check for primality.

    Returns:
        bool: True if `num` is a prime number, False otherwise.
    """
    try:
        if not isinstance(num, int):
            return False
        if num <= 1:
            return False
        if num <= 3:
            return True
        if num % 2 == 0 or num % 3 == 0:
            return False
        i = 5
        while i * i <= num:
            if num % i == 0 or num % (i + 2) == 0:
                return False
            i += 6
        return True
    except Exception:
        return False

def generate_numbers(n, rules) -> int:
    """
    Generate all unique numbers from the given number by applying transformation rules.
    Each rule allows a single digit to be transformed into another. The function
    returns the count of unique numbers that can be generated from the original
    number, including the number itself.

    Args:
        n (int): The original integer number to transform.
        rules (list of tuples): A list of transformation rules, where each
            rule is represented as a tuple (x, y) indicating that digit x can
            be transformed into y.

    Returns:
        int: The total count of unique numbers that can be generated.
    """
    # Basic validation
    if not isinstance(n, int):
        raise TypeError("n must be an integer")
    if not isinstance(rules, list):
        raise TypeError("rules must be a list of tuples")
    for rule in rules:
        if not isinstance(rule, tuple) or len(rule) != 2:
            raise ValueError("each rule must be a tuple of two elements")
        if not (isinstance(rule[0], int) and isinstance(rule[1], int)):
            raise ValueError("rule elements must be integers")

    # Convert number to string for easier digit manipulation
    original = str(n)
    visited = set([original])
    queue = [original]

    # Preprocess rules into a dictionary mapping source digit to list of targets
    rule_map = {}
    for src, tgt in rules:
        if not 0 <= src <= 9 or not 0 <= tgt <= 9:
            continue  # ignore rules with invalid digits
        rule_map.setdefault(str(src), []).append(str(tgt))

    while queue:
        current = queue.pop(0)
        for i, ch in enumerate(current):
            if ch in rule_map:
                for tgt in rule_map[ch]:
                    new_num = current[:i] + tgt + current[i+1:]
                    if new_num not in visited:
                        visited.add(new_num)
                        queue.append(new_num)

    return len(visited)

def check_scenario(scenario: str, liar_count: set, statements: dict, days_of_week: set) -> bool:
    """
    Evaluates the consistency of a scenario where one participant is the criminal based on the
    given statements.

    Parameters:
    - scenario (str): The name of the participant being tested as the potential criminal.
    - liar_count (set): A set of names of participants who are assumed to be liars.
    - statements (dict): A dictionary mapping participant names to lists of their respective statements.
    - days_of_week (set): A set of strings representing the days of the week.

    Returns:
    - bool: True if the scenario is consistent with the statements, False otherwise.
    """

    # Helper to determine if a single statement is true under the given scenario.
    def is_statement_true(speaker: str, stmt: str, criminal: str) -> bool:
        stmt_clean = stmt.strip().strip('.').upper()
        # Skip statements referencing days of the week
        words = [w.strip('.,!?') for w in stmt_clean.split()]
        if any(day.upper() in words for day in days_of_week):
            return True  # Ignore such statements; treat as neutral

        # Self statements
        if stmt_clean == "I AM GUILTY":
            return criminal.upper() == speaker.upper()
        if stmt_clean == "I AM NOT GUILTY":
            return criminal.upper() != speaker.upper()

        # Statements about others
        if len(words) == 3 and words[1] == "IS" and words[2] == "GUILTY":
            victim = words[0]
            return criminal.upper() == victim.upper()
        if len(words) == 4 and words[1] == "IS" and words[2] == "NOT" and words[3] == "GUILTY":
            victim = words[0]
            return criminal.upper() != victim.upper()

        # Unknown statement format: treat as neutral (cannot invalidate the scenario)
        return True

    criminal_upper = scenario.upper()
    for speaker, stmt_list in statements.items():
        is_liar = speaker.upper() in (name.upper() for name in liar_count)
        for stmt in stmt_list:
            try:
                truth = is_statement_true(speaker, stmt, criminal_upper)
            except Exception:
                # In case of unexpected format, consider the statement neutral
                continue
            if is_liar and truth:
                return False  # True statement from liar is impossible
            if not is_liar and not truth:
                return False  # False statement from truth-teller is impossible
    return True

