    A choir formation is defined such that for some position 'i', the heights of students
    increase from the start to 'i' and decrease from 'i' to the end of the formation.

    Args:
        heights (List[int]): A list of student heights.

    Returns:
        int: The minimum number of students that need to leave.
    """
    # Validate input
    if not isinstance(heights, list):
        raise TypeError("heights must be a list of integers")
    for h in heights:
        if not isinstance(h, int):
            raise TypeError("all elements in heights must be integers")

    n = len(heights)
    if n == 0:
        return 0

    # Compute LIS (Longest Increasing Subsequence) ending at each position
    lis = [1] * n
    for i in range(n):
        for j in range(i):
            if heights[j] < heights[i] and lis[j] + 1 > lis[i]:
                lis[i] = lis[j] + 1

    # Compute LDS (Longest Decreasing Subsequence) starting at each position
    lds = [1] * n
    for i in range(n - 1, -1, -1):
        for j in range(i + 1, n):
            if heights[j] < heights[i] and lds[j] + 1 > lds[i]:
                lds[i] = lds[j] + 1

    # Find maximum length of bitonic subsequence
    max_len = 0
    for i in range(n):
        # lis[i] and lds[i] both include the peak element at position i
        bitonic_len = lis[i] + lds[i] - 1
        if bitonic_len > max_len:
            max_len = bitonic_len

    # Minimum removals needed
    return n - max_len

